entries[225634] = { ["name"] = "Eingesponnene Kuriosität", ["text"] = "Wird beim Aufheben gebunden\n\"Schlussendlich half Königin Ansureks Verfolgungswahn weder ihr noch ihrem Volk. Kir'xal in der Nähe der Spinnennetze im Bau könnte vielleicht einen Nutzen hierfür finden.\"\nVerkaufspreis:" }
entries[225635] = { ["name"] = "Zev'kalls Zermürbungsprotokoll", ["text"] = "Questgegenstand\n\"Eine detaillierte Beschreibung der Verluste der nerubischen Truppen an der Belagerungsfeste.\"" }
entries[225636] = { ["name"] = "Königsmord", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n1,545 - 2,575 Schaden Geschwindigkeit 1.80\n(1,144 Schaden pro Sekunde)\n+1.007 Beweglichkeit\n+4.475 Ausdauer\nErhöht Eure Tempowertung um + 473.\nErhöht Eure Meisterschaftswertung um + 228.\nHaltbarkeit 80 / 80\n\"Nicht persönlich gemeint.\"\nVerkaufspreis:" }
entries[225637] = { ["name"] = "Vergifteter Dolch", ["text"] = "Questgegenstand\n\"Dieser vergiftete Dolch ist am Griff mit Pheromonen beschmiert.\"" }
entries[225638] = { ["name"] = "Schwindende Kerze des Höhlenforschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\nAnlegen: Eure schädlichen Zauber und Fähigkeiten haben eine Chance, dass eine Kerze des Höhlenforschers auf Eurem Kopf platziert wird, die Euch 15 Sek. lang einen kritischen Trefferwert von 1108 gewährt.\n\nWenn Ihr Euch einem Verbündeten bis auf 3 Meter annähert, wird auch ihm eine Kerze des Höhlenforschers gewährt und Ihr profitiert für die verbleibende Dauer beide vom Effekt.\nVerkaufspreis:" }
entries[225639] = { ["name"] = "Rezept: Ausgezeichnet ausgeweidete Muskeln", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ausgezeichnet ausgeweidete Muskeln zubereitet.\nRezept für 2 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:" }
entries[225640] = { ["name"] = "Abyssischer Köder", ["text"] = "Questgegenstand\nEinzigartig\n78 ( 78)\n\"Dunkle Kristallstücke, die von Treibholz und Tang zusammengehalten werden.\"" }
entries[225641] = { ["name"] = "Trügerischer Kobyssköder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Nimmt 30 Min. lang das Antlitz eines Kobyss an. (1 Stunde Abklingzeit)\n\"Wenn diese Dinger sie zu mir machen, was macht dann...?\"\nVerkaufspreis:" }
entries[225642] = { ["name"] = "Akolythenbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n396 Rüstung\n+634 Intelligenz\n+2.323 Ausdauer\n+ 888 Zufallswert 1\n\nTüfteleisockel\n\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[225643] = { ["name"] = "Höhlenforscherbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Leder\n681 Rüstung\n+634 [Beweglichkeit oder Intelligenz]\n+2.323 Ausdauer\n+ 888 Zufallswert 1\n\nTüfteleisockel\n\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[225644] = { ["name"] = "Fährtenleserbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Kette\n1004 Rüstung\n+634 [Beweglichkeit oder Intelligenz]\n+2.323 Ausdauer\n+ 888 Zufallswert 1\n\nTüfteleisockel\n\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[225645] = { ["name"] = "Gräberbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Platte\n1510 Rüstung\n+634 [Stärke oder Intelligenz]\n+2.323 Ausdauer\n+ 888 Zufallswert 1\n\nTüfteleisockel\n\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[225646] = { ["name"] = "4UT0-Z13L3R", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n1,002 - 1,862 Schaden Geschwindigkeit 3.00\n(477.3 Schaden pro Sekunde)\n+634 Beweglichkeit\n+2.323 Ausdauer\n+ 444 Zufallswert 1\n+ 444 Zufallswert 2\nHaltbarkeit 100 / 100\n\"Subtil steht nicht in den Spezifikationen dieser Waffe.\"\nVerkaufspreis:" }
entries[225647] = { ["name"] = "Leuchtende Arathorinsignie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 493.\nAnlegen: Ihr gehört zu den Ergebenen. Eure Zauber und Fähigkeiten haben eine Chance, einen Gegner in der Nähe zu verbrennen, um ihm 21998 Strahlenschaden zuzufügen, während ein anderer andächtiger Verbündeter um die gleiche Menge geheilt wird.\nVerkaufspreis:" }
entries[225648] = { ["name"] = "Kerzenvertrauter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, die Kerze zum Leben zu erwecken. Beschwört einen wächsernen Verbündeten, der Euren Gegnern einheizt.\nVerkaufspreis:" }
entries[225649] = { ["name"] = "Schnelldochtkerzenhalter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: <Klasse> ist flinker, <Klasse> ist behänder, <Klasse> erweckt die Macht vom Kerzenständer. Erhöht 20 Sek. lang die Bewegungsgeschwindigkeit um 20% und das Tempo um 2365 . (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[225651] = { ["name"] = "Emblem der Schattenweberin der Kaheti", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nAnlegen: Eure schädlichen Zauber haben eine hohe Chance, mit einem dunklen Ritual zu resonieren und Magie im Emblem zu speichern.\nBenutzen: Schließt das Ritual ab und entfesselt einen grauenvollen Strahl, der Eurem Ziel ( 1 * 7162 ) Schattenschaden pro gespeicherter Magie zufügt, bis zu [Quellwert]. (1 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[225653] = { ["name"] = "Entziehendes Lichtbrandzeichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\nAnlegen: Beim Erleiden von Schaden besteht eine hohe Chance, den Angreifer mit einem Brandmal zu versehen, das 5730 Heiligfeuerschaden verursacht und Euch um 50% des verursachten Schadens heilt.\nVerkaufspreis:" }
entries[225654] = { ["name"] = "Imperfektes Aufstiegsserum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+195 [Beweglichkeit oder Stärke oder Intelligenz]\nErhöht Eure Tempowertung um + 246.\nBenutzen: Trinkt aus der Phiole und steigt im Verlauf von 1,5 Sek. auf, bevor Ihr eine neue mächtigere Gestalt annehmt. Erhöht Eure Hauptwert um 778 und alle anderen Werte um 296 , aber nur für 20 Sek. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[225655] = { ["name"] = "Duftende Moorsporen", ["text"] = "Questgegenstand\n80 ( 80)\n\"Die Luft um sie herum ist unerklärlich abgestanden.\"" }
entries[225656] = { ["name"] = "Goldleuchten-Weihrauchschwenker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nBenutzen: Hüllt ein einzelnes verbündetes Ziel ins Leuchten des Räuchergefäßes. Gewährt einen Schild, der 15 Sek. lang bis zu 46257 Schaden absorbiert. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[225657] = { ["name"] = "Abnehmbarer Zahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\nAnlegen: Eure schädlichen Nahkampffähigkeiten haben eine Chance, 'Knirscher' auf Euer Ziel anzuwenden und ihm ( 1 * 8526 ) körperlichen Schaden zuzufügen. Jede dritte Anwendung von 'Knirscher' auf dasselbe Ziels verursacht zusätzlichen Schaden basierend auf der fehlenden Gesundheit des Ziels. Wenn 'Knirscher' ein anderes Ziel trifft, wird der Zähler zurückgesetzt.\nVerkaufspreis:" }
entries[225659] = { ["name"] = "Arathi-Buchsammlung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lest in dem neuesten Buch weiter, das Ihr zuletzt begonnen habt. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[225660] = { ["name"] = "Hammer des irdenen Meisters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repariert eine Waffe oder ein Plattenrüstungsteil, auf deren bzw. dessen Reparatur Ihr Euch spezialisiert habt.\nBenötigt Schmiedekunst von Khaz Algar (25)\nVerkaufspreis:" }
entries[225664] = { ["name"] = "Schusswaffe von Golemlord Argelmach", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[225665] = { ["name"] = "Schraubenschlüssel von Golemlord Argelmach", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[225666] = { ["name"] = "Axt von General Zornesschmied", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Axt\n1 - 2 Schaden Geschwindigkeit 3.20\n(0.5 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[225667] = { ["name"] = "Dreizack von Botschafter Flammenschlag", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[225668] = { ["name"] = "Instabiler Machtanzugkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nAnlegen: Die instabilen Energien des Kerns erhöhen zufällig einen Eurer Sekundärwerte um 517 . Dies hält 10 bis 30 Sek. an, bevor zufällig ein anderer Wert erhöht wird.\nVerkaufspreis:" }
entries[225669] = { ["name"] = "Götze der brutalen Kraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nVerkaufspreis:" }
entries[225670] = { ["name"] = "Herstellungslizenz des Lehrlings", ["text"] = "Fertigungshandwerksmaterial\n+100 Rezeptschwierigkeit\nBei der Herstellung: Erhöht Fertigkeit um 5.\nBenutzbar mit: Viele Khaz-Algar-Techniken in allen Berufen.\n\"Beim Feilbieten Eurer Waren bringt ein wenig Authentizität schon eine Menge. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[225671] = { ["name"] = "Stapel Pentagoldbewertungen", ["text"] = "Fertigungshandwerksmaterial\n+100 Rezeptschwierigkeit\nBei der Herstellung: Erhöht Fertigkeit um 10.\nBenutzbar mit: Viele Khaz-Algar-Techniken in allen Berufen.\n\"Ein kleiner Schub Selbstvertrauen von Euren meist geschätzten Kunden. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[225672] = { ["name"] = "Entwirrte Anweisungen", ["text"] = "Fertigungshandwerksmaterial\n+100 Rezeptschwierigkeit\nBei der Herstellung: Erhöht Fertigkeit um 20.\nBenutzbar mit: Viele Khaz-Algar-Techniken in allen Berufen.\n\"Manchmal ist es doch besser, sich nicht allein auf sein Gedächtnis zu verlassen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[225673] = { ["name"] = "Gütesiegel des Handwerkerkonsortiums", ["text"] = "Wird beim Aufheben gebunden\nFertigungshandwerksmaterial\n\nBei der Herstellung: Erhöht Fertigkeit um 40.\nBenutzbar mit: Viele Khaz-Algar-Techniken in allen Berufen.\n\"Ein Preis für hochangesehene Handwerker\"\nVerkaufspreis:" }
entries[225674] = { ["name"] = "Zerbrochenes Steinherz", ["text"] = "Questgegenstand\n\"Zerbrochen, aber zu reparieren.\"" }
entries[225677] = { ["name"] = "Schimmerndes Chaos", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Wandelt Schimmerndes Transmutagen in eine Auswahl zufälliger Materialien um.\"\nVerkaufspreis:" }
entries[225678] = { ["name"] = "Ersatzschlüssel für Shaffars Stasiskammer", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet Nexus-Prinz Shaffars Stasiskammer." }
entries[225679] = { ["name"] = "Vorlage: Robuster Blutstein", ["text"] = "Benutzen: Lehrt Euch, wie man einen robusten Blutstein herstellt.\nBenötigt Juwelierskunst von Khaz Algar\n(50)\nVerkaufspreis:" }
entries[225680] = { ["name"] = "Vorlage: Kognitiver Blutstein", ["text"] = "Benutzen: Lehrt Euch, wie man einen kognitiven Blutstein herstellt.\nBenötigt Juwelierskunst von Khaz Algar\n(50)\nVerkaufspreis:" }
entries[225681] = { ["name"] = "Vorlage: Entschlossener Blutstein", ["text"] = "Benutzen: Lehrt Euch, wie man einen entschlossenen Blutstein herstellt.\nBenötigt Juwelierskunst von Khaz Algar\n(50)\nVerkaufspreis:" }
