entries[225683] = { ["name"] = "Greifendes Relikt der Nekrotischen Fäulnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nVerkaufspreis:" }
entries[225684] = { ["name"] = "Reliktblut von Zekvir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nVerkaufspreis:" }
entries[225685] = { ["name"] = "Relikt der Empfindungsfähigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nVerkaufspreis:" }
entries[225692] = { ["name"] = "Glühglühkappe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Von Euch geht ein schwaches Leuchten aus. Die Dunkelheit vermag sie nicht zu vertreiben, aber sie offenbart 5 Min. lang durch die Dunkelheit verborgene Geheimnisse.\n\nSolange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen.\n\"Mit einer leuchtenden Pilzkappe kann jeder zum Alleinunterhalter werden.\"\nVerkaufspreis:" }
entries[225693] = { ["name"] = "Schattige Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Beschwört bei Eintritt in den Kampf eine Kugel dunkler Macht, die Euch unterstützt.\nVerkaufspreis:" }
entries[225696] = { ["name"] = "Verderbtes Herz", ["text"] = "Questgegenstand\n\"Das verdorbene Herz eines Tiefenläufers, zu mitgenommen, um wieder mit der Realität zu harmonieren.\"" }
entries[225697] = { ["name"] = "Blindes Auge", ["text"] = "Questgegenstand\n\"Ein Augapfel, der nur im Ungehörigen sehen kann und die ursprüngliche Realität seines Besitzers nicht länger wahrnimmt.\"" }
entries[225698] = { ["name"] = "Wurzelbruchstück", ["text"] = "Questgegenstand\n\"Ein kleines Stück einer Wurzel, die einst zu einem Baum gehörte und jetzt in einem Haufen schleimiger Überreste gefunden wurde.\"" }
entries[225709] = { ["name"] = "Brax' linker Schuh", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Man sollte meinen, er hätte seine Abwesenheit gemerkt.\"\nVerkaufspreis:" }
