entries[225883] = { ["name"] = "Vorbereiteter Geisterfisch", ["text"] = "Handwerksmaterial\n\"Respektvoll vorbereitet, sowohl in Hinblick auf seinen Ursprung und sein Ziel. Wird von Köchen hergestellt, die verfluchten Geisterfisch filetieren. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
