entries[225886] = { ["name"] = "Zerschmetterte Reliktfragmente", ["text"] = "Questgegenstand\n73 ( 73)\n\"Jedes Fragment erzählt eine tausend Jahre alte Geschichte.\"" }
entries[225887] = { ["name"] = "Titanenemitter", ["text"] = "Questgegenstand\n73 ( 73)\n\"Die titanischen Runen, die in die Oberfläche geritzt sind, scheinen ein schwaches Signal auszusenden.\"" }
entries[225888] = { ["name"] = "Titanenemitter", ["text"] = "Questgegenstand\nEinzigartig\n73 ( 73)\n\"Welche Geheimnisse finden sich darin?\"" }
entries[225891] = { ["name"] = "Üble Phiole voll Kahetigalle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nAnlegen: Eure Heilzauber und -fähigkeiten haben eine Chance, dass sich die Phiole arglistig auf Euren Verbündeten mit der niedrigsten Gesundheit stürzt, um ihn um 18200 Gesundheit zu heilen.\n\"Das Fläschchen schimmert und wird durch vergessene Magie zum Leben erweckt. Seine Absicht ist es, zu schaden. Sein Inhalt ist ein starkes Heilmittel.\"\nVerkaufspreis:" }
entries[225892] = { ["name"] = "Rezept: Felssturzmischgetränk", ["text"] = "Benutzen: Lehrt Euch, wie man ein Felssturzmischgetränk herstellt.\nRezept für 10 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:" }
