entries[225912] = { ["name"] = "Heiße Honigwabe", ["text"] = "Fertigungshandwerksmaterial\n\nBei der Herstellung: Gebt ein wenig von dieser Geheimzutat hinzu, um eine Chance darauf zu erhalten, die Anzahl der zubereiteten Portionen zu erhöhen.\nBenutzbar mit: Rezepte aus Khaz Algar.\n\"Wenn der Magen besonders laut knurrt. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[225913] = { ["name"] = "Sonderarbeitsgenehmigung", ["text"] = "Questgegenstand\n\"Verleiht die Befugnis, mit den Minenarbeitern bei der Abyssausgrabung zu sprechen und zu arbeiten.\"" }
entries[225927] = { ["name"] = "Smaragdgrüne Halskette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Das Juwel pulsiert vor arkaner Energie und weist auf uralte Magie hin, die bis tief in seinen Kern gewoben wurde.\"" }
entries[225930] = { ["name"] = "Funkelnder Kristall", ["text"] = "Blauer Nebel erfüllt Eure Sicht und ermöglicht es Euch, astrale Kreaturen zu sehen.\n\"Ein funkelnder, lilafarbener Kristall, der in einem eigenen Licht zu glühen scheint.\"" }
entries[225931] = { ["name"] = "Vertragsgebühr", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Nichts sagt \"Ich liebe dich\" mehr als ein schwerer Sack voll Gold.\"" }
