entries[226040] = { ["name"] = "Goldener Krokilisk des Plünderfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den goldenen Krokilisk des Plünderfürsten oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Was wäre ein Plünderfürst, wenn er seine geplünderten Schätze nicht zur Schau stellte?\"\nHandelsposten" }
entries[226041] = { ["name"] = "Strahlender Krokilisk von Fasshaxe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen strahlenden Krokilisken von Fasshaxe oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Der Piratenkapitän, der später als Fasshaxe bekannt wurde, war sich des Risikos bewusst, auf einem hungrigen Krokilisken in die Schlacht zu reiten.\"\nHandelsposten" }
