entries[226357] = { ["name"] = "Diamantener Mechanzug", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese kristallbetriebenen Mechanzüge stellen die technologische Spitze der Irdenen Föderation dar.\"\nErfolg:\nSchlüsselsteinmeister von The War Within: Saison 1\nKategorie:\nDungeons" }
entries[226358] = { ["name"] = "Ersatzuniform der Venture Company", ["text"] = "Questgegenstand\nBenutzen: Zieht eine Venture-Co.-Verkleidung an, sodass Ihr mit den Angestellten auf den Halden sprechen könnt. Kann nur in Nähe dieses Gebiets benutzt werden.\n\nFalls Ihr Eure Uniform verliert, könnt Ihr jederzeit eine weitere anziehen. (5 Sek. Abklingzeit)\n\"Passt Euch schon. Irgendwie.\"" }
entries[226361] = { ["name"] = "Reittierliste für die Wettkämpfe der nächsten Woche", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Es scheint sich dabei um die Reittierliste für die Wettkämpfe der nächsten Woche zu handeln.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[226362] = { ["name"] = "Zerrissene Notiz", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[226363] = { ["name"] = "Rucksack der Irdenen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226364] = { ["name"] = "Zerrissene Notiz", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[226365] = { ["name"] = "Zusammengeknüllter Brief", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[226366] = { ["name"] = "Handschuhe des Morgendunstes", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\n\"Die Kürbiskutsche ist leider nicht inklusive.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226367] = { ["name"] = "Hässliche schwarze Stiefel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nFüße Kosmetisch\n\"Perfekt, um Euch durch einen alltäglichen und doch magischen Tag zu begleiten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[226368] = { ["name"] = "Hässliche weiße Stiefel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nFüße Kosmetisch\n\"Gemütlich und warm, und heiß begehrt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[226369] = { ["name"] = "Klassischer verblasster Wappenrock", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\n\"Ein einfacher Wappenrock für trostlose Anlässe.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[226370] = { ["name"] = "Aschener Scharfrichter", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\n\"Befleckt von Asche und Ruß, die aus den Tiefen der Schwarzfelsgießerei emporsteigen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226372] = { ["name"] = "Noggenfogger Deluxe mit Limone", ["text"] = "Questgegenstand\nBenutzen: Seehorn geben, um ihn zu ermächtigen!\n\"Unberechenbar und tropisch.\"" }
entries[226373] = { ["name"] = "Noggenfoggers immerwährendes Elixier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bietet das Mundgefühl von Öl mit dem salzigen Geschmack einer Auster. Köstlich.\n\nKostet 50 Silber pro Schluck. (3 Sek. Abklingzeit)\nErfordert einen respektvollen Ruf beim Dampfdruckkartell in Lorenhall.\n\"Die Farbe, der Geruch, die Transformationen! Das Elixier ist das, wovon Barden sprechen, wenn sie die Mengen mit Geschichten vom Ambrosia der Goblins entzücken.\"\nVerkaufspreis:" }
entries[226375] = { ["name"] = "Ramponierte Feierkiste", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
