entries[226387] = { ["name"] = "Kampferprobter Kriegshammer", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\n\"Doppelt so schwer und halb so wirksam wie ein durchschnittlicher Hammer.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226388] = { ["name"] = "Kampferprobter Obsidiankriegshammer", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Streitkolben\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\n\"Nur der stärkste Obsidian kann dem Druck standhalten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226389] = { ["name"] = "Dunkeleisenschlachtkolben", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Der Streitkolben aus dunklem Eisen wurde vor langer Zeit für jeden der Klankönige geschmiedet, aber ging bei inneren Streitigkeiten für ganze Zeitalter verloren.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226390] = { ["name"] = "Adlerhorstschlachtkolben", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Diese Waffe wurde vor langer Zeit in der Großen Schmiede gefertigt und von den größten Champions unter Khardros' Wildhammern geschwungen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[226391] = { ["name"] = "Britzelnde Taserklinge", ["text"] = "Questgegenstand\n\"Eine dunkle, zähflüssige Masse tropft davon herunter. Ist das... Schwarzblut?\"" }
entries[226392] = { ["name"] = "Schatz des sorglosen Flitzers", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 1 Angelfestabzeichen von Mereldar.\n80 ( 80)\n\"Seht immer in Euren Taschen nach, bevor Ihr durch Khaz Algar rast.\"" }
entries[226393] = { ["name"] = "Jetpack-im-Kasten", ["text"] = "Questgegenstand\nBenutzen: Legt ein Jetpack an, das Euch 30 Sek. lang ermöglicht, innerhalb von Lorenhall zu fliegen. Explodiert bei Ablauf oder wenn Ihr landet. (5 Sek. Abklingzeit)\n\"Warnung: Nicht für den Gebrauch in Innenbereichen. Oder den Gebrauch im Freien. Wenn Ihr Euch dazu entscheidet, unser Produkt auf irgendeine Weise zu verwenden, ist das Euer Problem.\"" }
