entries[226505] = { ["name"] = "Nerubischer Edelsteinweber", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem Gegenstand der Saison 1 von War Within, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Armschienen oder Gürtel angewandt werden. Kann nicht für PvP-Ausrüstung verwendet werden." }
entries[226506] = { ["name"] = "Hand von Reshkigaal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Reshkigaal wartete ab, während ihr Volk versuchte, den Verbannten an sich zu reißen. Sie wollte angreifen, wenn er abgelenkt war, aber die Spione des Gefängniswärters hatten sie aufgespürt. Mit ihrer Warnung und Hilfe gewann der Gefängniswärter die Oberhand.\"\nHandelsposten" }
entries[226507] = { ["name"] = "Spinnwebentinktur des Giftigen Dahns", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Reibt Euch mit Huschergift ein, um einen Stapel von 'Mal des Auslöschers' zu entfernen.\nErfordert den Ruf 'Kumpane' beim General.\n\"Eine giftbasierte Körpertinktur, um Schmutz und Spinnweben vom Mal des Auslöschers zu entfernen. 88% natürliche Aromen!\"" }
entries[226508] = { ["name"] = "Einfluss des Wesirs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr habt die richtigen Neruber bestochen.\n\nWenn die Wachen Euch das nächste Mal aus der Stadt der Fäden verbannen wollen, werdet Ihr stattdessen zum königlichen Apothekarium geschickt. Dieser Effekt bleibt 60 Minuten lang bestehen.\nErfordert den Ruf 'Komplize' beim Wesir.\n\"Eine Reihe \"offizieller\" Dokumente. \"Überzeugt\" die Wachen in der Stadt der Fäden davon, Euch zum Königlichen Apotheker zu bringen, wenn sie Euch erwischen.\"" }
entries[226509] = { ["name"] = "Einsicht des Generals", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr könnt den Erkennungsradius der Wachen in der Stadt der Fäden 10 Minuten lang visualisieren.\n\nIhr habt viel vom General gelernt.\nErfordert den Ruf 'Komplize' beim General.\n\"Eine Kopie der Surekipatrouillen und -methoden. Damit könnt Ihr den Erkennungsradius aller Wachen in der Stadt der Fäden sehen.\"" }
entries[226510] = { ["name"] = "Weberfassade", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr nehmt das Antlitz eines wahren Nerubers an. Wachen in der Stadt der Fäden haben nun eine Minute lang einen verringerten Erkennungsradius.\n\nDie Weberin ist meisterlich im Verkleiden.\nErfordert den Ruf 'Komplize' bei der Weberin.\n\"Eine Pheromonmischung, die Wachen in der Stadt der Fäden narrt und ihren Erkennungsradius deutlich verringert. Eine Spezialität der Weber.\"" }
entries[226511] = { ["name"] = "Nerubimorphmaske", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Werft ein Gebräu, um eine Wache in der Stadt der Fäden 30 Sekunden lang in eine weniger bedrohliche Gestalt zu verwandeln.\n\nEin Spezialrezept des Wesirs höchstpersönlich.\nErfordert den Ruf 'Kumpane' beim Wesir.\nErfordert den Ruf 'Kumpane' bei der Weberin.\n\"Eine Mischung zum Werfen, die Opfer für kurze Zeit in harmlose Weberatten verwandelt. Funktioniert nur bei Wachen in der Stadt der Fäden.\"" }
entries[226512] = { ["name"] = "Schatzkarte: Vergessenes Denkmal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort eines vergessenen Denkmals auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' beim General." }
entries[226513] = { ["name"] = "Schatzkarte: Kahetiausgrabung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort einer Kahetiausgrabung auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' beim Wesir." }
entries[226514] = { ["name"] = "Schatzkarte: Weberattenschatz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort eines Weberattenschatzes auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' bei der Weberin." }
entries[226515] = { ["name"] = "Gerüchtekarte: Kopfgeld", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort eines Kopfgeldgerüchts auf Eurer Karte auf." }
entries[226516] = { ["name"] = "Gerüchtekarte: Störung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort eines Störungsgerüchts auf Eurer Karte auf." }
entries[226517] = { ["name"] = "Gerüchtekarte: Spionage", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort eines Spionagegerüchts auf Eurer Karte auf." }
entries[226518] = { ["name"] = "Pheroflucht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt verschiedene Pheromone implodieren, die Wachen in der Stadt der Fäden 2 Sekunden lange betäuben, damit Ihr aus dem Kampf entkommt.\nErfordert den Ruf 'Kumpane' beim Wesir.\n\"Werft diese Implosion aus Pheromonen, um Gegner zu betäuben und aus dem Kampf zu fliehen. Funktioniert nur gegen Wachen in der Stadt der Fäden.\"" }
entries[226519] = { ["name"] = "Expertise des Generals", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ihr könnt den Erkennungsradius der Wachen in der Stadt der Fäden visualisieren.\n\nIhr habt viel vom General gelernt.\nErfordert den Ruf 'Kumpane' bei der Weberin, dem General oder dem Wesir.\n\"Eine abgeschriebene Kopie des Kampfleitfadens, den alle Soldaten in Azj-Kahet verinnerlicht haben. Wenn sie aktiv ist, könnt Ihr den Erkennungsradius aller Wachen in der Stadt der Fäden sehen.\"" }
entries[226520] = { ["name"] = "Pheromone der Königin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Pheromone der Königin.\n\nWachen in der Stadt der Fäden stellen sich Euch nicht mehr in den Weg.\nErfordert den Ruf 'Strippenzieher' bei der Weberin, dem General oder dem Wesir.\n\"Die Pheromone der Königin. Diskret erlangt. Wachen in der Stadt der Fäden können Euch nicht mehr entdecken.\"" }
entries[226521] = { ["name"] = "Verstärkte Wachspanzerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\nAnlegen: Trägt eine dicke Schicht verstärkten Wachses auf Eure Rüstung auf, die 1922 Schadensverringerung gewährt.\nVerkaufspreis:" }
entries[226522] = { ["name"] = "Fragment der Demolierungssteuerung", ["text"] = "Questgegenstand\n\"Zwischen den Kabeln stecken einige Sandkörner fest.\"" }
entries[226524] = { ["name"] = "Teilweise aufgeladener Holostein", ["text"] = "Völker: Draenei , Lichtgeschmiedeter Draenei\nBenutzen: Aktiviert den Holostein. (30 Sek. Abklingzeit)\n\"Hat gerade genug Energie, um für kurze Zeit eingesetzt zu werden.\"\nVerkaufspreis:" }
entries[226525] = { ["name"] = "Abrisskontrollcode", ["text"] = "Questgegenstand" }
entries[226539] = { ["name"] = "Schriftrolle des Momentums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Beweglichkeit\nAnlegen: Eure schädlichen Angriffe und Fähigkeiten haben eine hohe Chance, Momentum aufzubauen, wodurch Ihr pro Stapel 2% zusätzliche Bewegungsgeschwindigkeit erhaltet.\n\nBei 5 Stapeln erreicht Ihr volles Momentum, wodurch Euer Bewegungsgeschwindigkeitsbonus 10 Sek. lang auf 20% erhöht wird. Bei vollem Momentum treffen Eure Angriffe das Ziel mit Hochgeschwindigkeit und verursachen ( 1 * 2869 ) zusätzlichen Naturschaden, der mit Eurer aktuellen Bewegungsgeschwindigkeit skaliert. (500ms Abklingzeit)\nVerkaufspreis:" }
entries[226643] = { ["name"] = "Pläne: Beledars Bollwerk", ["text"] = "Benutzen: Lehrt Euch, wie man Beledars Bollwerk herstellt.\nBenötigt Schmiedekunst von Khaz Algar (35)\nVerkaufspreis:" }
entries[226672] = { ["name"] = "Band des elementaren Chaos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+636 Ausdauer\n+ 751 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 563.\nVerkaufspreis:" }
entries[226681] = { ["name"] = "Zischender Glutpollen", ["text"] = "\"Verursacht besonders schmerzhafte Niesanfälle. Dank Euren Bemühungen hat die Metbrauerei eine ganze Menge davon auf Lager.\"\nVerkaufspreis:" }
entries[226683] = { ["name"] = "Defekter Mechanzug", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine Maschine, die ihre vorgesehene Form verloren hat.\"" }
entries[226689] = { ["name"] = "Kopf des schmutzigen Erntegolems", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
