entries[226695] = { ["name"] = "Gunst des gerissenen Beraters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+5.034 Ausdauer\n+ 2.689 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 556.\n\"Anub'arash würde Weisheit nicht erkennen, selbst wenn sie den Palast stürmte! Also, wie werden wir ihn los...\"\nVerkaufspreis:" }
entries[226696] = { ["name"] = "Gunst des mächtigen Beraters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+5.034 Ausdauer\n+ 2.689 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 556.\n\"Hier ist eine Weisheit für Euch, Takazj: Stellt Euch mir nicht in den Weg.\"\nVerkaufspreis:" }
entries[226800] = { ["name"] = "Rucksack der Irdenen", ["text"] = "Wird beim Aufheben gebunden\nRücken\n2 Rüstung\n+1 [Beweglichkeit oder Stärke oder Intelligenz]\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 1 Vielseitigkeit\nVerkaufspreis:" }
entries[226810] = { ["name"] = "Schleier des Infiltrators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Nehmt 20 Min. lang die Erscheinung eines Leerenernters des Astraleums an. (1 Stunde Abklingzeit)\n\"Damit sieht Euch niemand kommen.\"\nVerkaufspreis:" }
entries[226811] = { ["name"] = "Marinierte Maden", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit und ( 675000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[226813] = { ["name"] = "Goldener Tapferkeitsstein", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 75 Tapferkeitssteine.\"\n<Zum Öffnen rechtsklicken>" }
entries[226814] = { ["name"] = "Truhe voller Gold", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 1.000 Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[226823] = { ["name"] = "Automatischer Greifhaken des Bilgewasserkartells", ["text"] = "Questgegenstand\nBenutzen: Wirft den Greifhaken nach einem V.O.G.E.L. innerhalb von 50 Metern und zieht ihn zu Euch. (5 Sek. Abklingzeit)\n\"Normalerweise zur Erhöhung der Reichweite von Sprengstoff gedacht, doch in der Garantie steht nicht, das etwas gegen den Einsatz beim Vogelfischen spricht.\"" }
entries[226824] = { ["name"] = "Handvoll V.O.G.E.L.-Teile", ["text"] = "Questgegenstand\n\"Ein Vielzahl an Schrauben, Zahnrädern, Platinen und Kabeln.\"" }
entries[226853] = { ["name"] = "Erzprobe", ["text"] = "Questgegenstand" }
entries[226854] = { ["name"] = "Zerknüllte Gehaltsabrechnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Von schmierigen Fingern verwischt, doch Ihr könnt die Adresse des Arbeitgebers noch ausmachen. Auf der Rückseite ist eine Notiz befestigt.\"" }
entries[227208] = { ["name"] = "Bismutrute", ["text"] = "Wird beim Anlegen gebunden\nWerkzeug für Verzauberkunst\n\"Dient als runenverzierte Verzauberkunstrute, auch wenn sie nicht sehr mächtig ist.\"" }
