entries[227362] = { ["name"] = "Al'ars goldene Asche", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Phönix oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der goldene Al'ar, geliebtes Haustier von Kael'thas Sonnenwanderer, beweist, dass der Tod nur ein kleiner Rückschlag ist.\"\nPromotion" }
