entries[227659] = { ["name"] = "Flüchtige arkane Manifestation", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Verzauberkunstwissen von Khaz Algar um 1 zu erhöhen.\n\"Eine Kugel aus konzentrierter arkaner Energie, perfekt für das Studium durch einen aufstrebenden Verzauberer.\"" }
entries[227660] = { ["name"] = "Belebte Kerze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Entzündet den Docht, um einen Wachsling zu beschwören, der Euch 1 Min. lang verteidigt.\nNur in Khaz Algar nutzbar. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[227661] = { ["name"] = "Strahlender tellurischer Kristall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Verzauberkunstwissen von Khaz Algar um 4 zu erhöhen.\n\"Ein kleiner Kristall, der aus konzentrierter, magischer Energie geformt ist. Ein Verzauberer könnte durch dessen Studium viel lernen.\"" }
entries[227662] = { ["name"] = "Schillernder Staub", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Verzauberkunstwissen von Khaz Algar um 1 zu erhöhen.\n\"Ein feines Pulver, das vor arkaner Magie glüht.\"" }
entries[227663] = { ["name"] = "Noggenfogger Empfehlung", ["text"] = "Questgegenstand\nEinzigartig\n\"Jo. Dieser Trottel hat keine Ahnung, was für hochwertiges Futter die Leute des Dampfdruckkartells machen können. Kocht etwas, das sie vom Hocker haut. Bonuspunkte, wenn der Hocker dabei explodiert.\"" }
entries[227664] = { ["name"] = "Geisterschwinges Pfeife", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\nBenutzen: Ruft Rexxar und Geisterschwinge herbei. (30 Sek. Abklingzeit)" }
