entries[227666] = { ["name"] = "Rezensionskarten für Speisende", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (200)\n\"Das beliebteste Gericht scheinen zerquetschte Bilgenager zu sein, abgerundet mit Pfefferkäse vom Talbuk und serviert mit einem druidischen Traumsalat als Beilage.\"" }
