entries[227673] = { ["name"] = "\"Gold\"-Fisch", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\n\"Ein Fisch. Zumindest war es das einmal? Ein optimistischer Goblin würde sagen, dass die Produkte des Dampfdruckkartells aus Möglichkeiten geschaffen sind. Sollte NICHT im Auktionshaus gekauft oder verkauft werden.\"\nVerkaufspreis:" }
entries[227674] = { ["name"] = "Gobdres geschätztes Bratgefäß", ["text"] = "Questgegenstand\n\"Eine gewöhnliche, durch jahrelange Verwendung abgenutzte Bratpfanne. Vielleicht kann Jojo Gobdre erklären, was sie so besonders macht.\"" }
