entries[227769] = { ["name"] = "Fülle an Bolzen", ["text"] = "Handwerksmaterial\n\"Man kann nie genug Bolzen haben. Wird von Ingenieuren von Khaz Algar genutzt, um den Meuteverprügler 2-30 zu bauen. Wird von Paxton Bombenhülse in den Schallenden Tiefen verkauft.\"\nVerkaufspreis:" }
