entries[227771] = { ["name"] = "Blinkerflüssigkeit", ["text"] = "Handwerksmaterial\n\"Angeblich eine unentbehrliche Zutat im Bau von funktionierenden Scheinwerfern. Wird von Ingenieuren von Khaz Algar genutzt, um den Meuteverprügler 2-30 zu bauen. Wird von Paxton Bombenhülse in den Schallenden Tiefen verkauft.\"\nVerkaufspreis:" }
