entries[227775] = { ["name"] = "Goldener Kelch", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Dieser Schatz ist vermutlich besser, als sich Maru und Enzo je erträumt hätten.\"" }
